import { readFile, writeFile, mkdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../", import.meta.url));
const check = process.argv.includes("--check");
const protocol = JSON.parse(
  await readFile(path.join(root, "packages/contracts/protocol.json"), "utf8"),
);
const tokens = JSON.parse(
  await readFile(path.join(root, "packages/design/tokens.json"), "utf8"),
);
const banner =
  "// Generated by scripts/generate-shared.mjs; edit the JSON source.\n";
const swiftContracts = `${banner}import Foundation\n\nenum Contracts {\n    static let apiVersion = ${protocol.apiVersion}\n    static let documentVersion = ${protocol.documentVersion}\n    static let autosaveMilliseconds = ${protocol.autosaveMilliseconds}\n}\n\nenum NoteLimits {\n${Object.entries(
  protocol.limits,
)
  .map(([key, value]) => `    static let ${key} = ${value}`)
  .join(
    "\n",
  )}\n}\n\nenum EditorAction: String, CaseIterable {\n${protocol.editorActions.map((action) => `    case ${action}`).join("\n")}\n}\n`;
const cssNames = {
  background: "bg",
  limeSoft: "lime-soft",
  onLime: "on-lime",
  accent: "snippet-accent",
  danger: "orange",
};
const variables = (mode) =>
  Object.entries(tokens.colors)
    .map(([key, values]) => `  --${cssNames[key] || key}: ${values[mode]};`)
    .join("\n");
const metrics = Object.entries(tokens)
  .filter(([key]) => key !== "colors")
  .flatMap(([group, values]) =>
    Object.entries(values).map(
      ([key, value]) =>
        `  --${group}-${key.replace(/[A-Z]/g, (c) => "-" + c.toLowerCase())}: ${value}px;`,
    ),
  )
  .join("\n");
const css = `/* Generated by scripts/generate-shared.mjs; edit packages/design/tokens.json. */\n:root, :host, :root[data-theme="light"] {\n${variables(0)}\n  --input: var(--surface);\n${metrics}\n}\n:root[data-theme="dark"], :host([data-theme="dark"]) {\n${variables(1)}\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme]), :host:not([data-theme]) {\n${variables(1)}\n  }\n}\n`;
const swiftTokens = `${banner}import SwiftUI\n#if canImport(UIKit)\nimport UIKit\n#elseif canImport(AppKit)\nimport AppKit\n#endif\n\nenum DesignTokens {\n    static func adaptive(_ light: UInt32, _ dark: UInt32) -> Color {\n        #if canImport(UIKit)\n        return Color(uiColor: UIColor { traits in\n            let rgb = traits.userInterfaceStyle == .dark ? dark : light\n            return UIColor(red: CGFloat((rgb >> 16) & 255) / 255, green: CGFloat((rgb >> 8) & 255) / 255, blue: CGFloat(rgb & 255) / 255, alpha: 1)\n        })\n        #else\n        return Color(nsColor: NSColor(name: nil) { appearance in\n            let rgb = appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua ? dark : light\n            return NSColor(red: CGFloat((rgb >> 16) & 255) / 255, green: CGFloat((rgb >> 8) & 255) / 255, blue: CGFloat(rgb & 255) / 255, alpha: 1)\n        })\n        #endif\n    }\n${Object.entries(
  tokens.colors,
)
  .map(
    ([key, values]) =>
      `    static let ${key} = adaptive(${values.map((v) => "0x" + v.slice(1).toUpperCase()).join(", ")})`,
  )
  .join("\n")}\n${Object.entries(tokens)
  .filter(([key]) => key !== "colors")
  .flatMap(([group, values]) =>
    Object.entries(values).map(
      ([key, value]) =>
        `    static let ${group}${key[0].toUpperCase() + key.slice(1)}: CGFloat = ${value}`,
    ),
  )
  .join("\n")}\n}\n`;
const outputs = new Map([
  [
    "packages/core/src/contracts.ts",
    `${banner}export const API_VERSION = ${protocol.apiVersion};\nexport const DOCUMENT_VERSION = ${protocol.documentVersion};\nexport const AUTOSAVE_MILLISECONDS = ${protocol.autosaveMilliseconds};\nexport const NOTE_LIMITS = ${JSON.stringify(protocol.limits, null, 2)} as const;\nexport const EDITOR_ACTIONS = ${JSON.stringify(protocol.editorActions)} as const;\nexport type EditorAction = typeof EDITOR_ACTIONS[number];\n`,
  ],
  [
    "extensions/clipper/src/contracts.js",
    `${banner}globalThis.DoompileContracts = ${JSON.stringify(protocol, null, 2)};\n`,
  ],
  ["apps/ios/Shared/Contracts.generated.swift", swiftContracts],
  ["packages/design/tokens.generated.css", css],
  ["apps/ios/Shared/DesignTokens.generated.swift", swiftTokens],
]);
let dirty = false;
for (const [relative, content] of outputs) {
  const filename = path.join(root, relative);
  const current = await readFile(filename, "utf8").catch(() => null);
  if (current === content) continue;
  if (check) {
    console.error(`Generated file is stale: ${relative}`);
    dirty = true;
  } else {
    await mkdir(path.dirname(filename), { recursive: true });
    await writeFile(filename, content);
  }
}
if (dirty) process.exitCode = 1;
